package org.eclipse.jdt.internal.ui.text.java;

import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.jdt.core.IMember;
import org.eclipse.jdt.core.JavaModelException;
import org.eclipse.jdt.internal.ui.text.javadoc.JavadocContentAccess2;

// This class demonstrates the usage of the deprecated method.
// Assumes existence of types like IMember, IProgressMonitor, JavaModelException, and JavadocContentAccess2.
public class ProposalInfo {
    private String extractJavadoc(IMember member, IProgressMonitor monitor) throws JavaModelException {
        if (member != null) {
            // Deprecated call with three arguments
            return JavadocContentAccess2.getHTMLContent(member, true, true);
        }
        return null;
    }
}

